import React from 'react';
import { Calendar, DatePicker } from '@gravity-ui/date-components';
import { dateTime, settings } from '@gravity-ui/date-utils';
import type { DateTime } from '@gravity-ui/date-utils';
import { Card, Flex, Text, configure } from '@gravity-ui/uikit';

// Язык интерфейса uikit (подписи дней недели, кнопки календаря и т.п.).
configure({ lang: 'ru' });

const DATE_FORMAT = 'DD.MM.YYYY';

export function App() {
  const [date, setDate] = React.useState<DateTime | null>(null);
  const [localeReady, setLocaleReady] = React.useState(false);

  // Подгружаем русскую локаль для названий месяцев и дней недели.
  React.useEffect(() => {
    let cancelled = false;
    settings
      .loadLocale('ru')
      .catch(() => undefined)
      .then(() => {
        if (!cancelled) setLocaleReady(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const handleUpdate = React.useCallback((value: DateTime | null) => {
    setDate(value);
  }, []);

  const today = React.useMemo(() => dateTime(), []);

  return (
    <Flex direction="column" gap={6} style={{ padding: 24, maxWidth: 480 }}>
      <Text variant="header-2" as="h1">
        Выбор даты
      </Text>

      <Flex direction="column" gap={2}>
        <Text variant="subheader-2" as="label" {...{ htmlFor: 'date-picker' }}>
          Дата
        </Text>
        <DatePicker
          id="date-picker"
          name="date"
          size="l"
          format={DATE_FORMAT}
          placeholder={DATE_FORMAT}
          hasClear
          value={date}
          onUpdate={handleUpdate}
          aria-label="Выбор даты"
        />
      </Flex>

      <Card view="outlined" style={{ padding: 16, alignSelf: 'flex-start' }}>
        {/* key заставляет календарь перерисоваться после загрузки локали */}
        <Calendar
          key={localeReady ? 'ru' : 'en'}
          size="l"
          value={date}
          onUpdate={handleUpdate}
          defaultFocusedValue={date ?? today}
          aria-label="Календарь"
        />
      </Card>

      <Text variant="body-2" color={date ? 'primary' : 'secondary'}>
        {date
          ? `Выбрана дата: ${date.format('D MMMM YYYY')} (${date.format(DATE_FORMAT)})`
          : 'Дата не выбрана'}
      </Text>
    </Flex>
  );
}
EOF
